'use client';
import {useState} from 'react'; import AppShell from '@/components/AppShell';
const exercises=[['DB Floor Press','4 × 10–15'],['One-arm Row','4 × 10–15 / side'],['Shoulder Press','3 × 8–12'],['Biceps Curl','3 × 10–15'],['Triceps Extension','3 × 10–15']];
export default function Workout(){const [done,setDone]=useState<Record<number,boolean>>({});return <AppShell><div className="pagehead"><div className="eyebrow">Dumbbell 10 kg</div><h1>Workout</h1><p className="muted">Upper • Lower • Full Body</p></div><section className="hero"><div className="eyebrow">Today • Upper</div><h2>Build strength while cutting.</h2><div className="progress"><div style={{width:`${Object.keys(done).filter(k=>done[+k]).length/exercises.length*100}%`}}/></div></section><section className="section"><h2>Exercises</h2><div className="list">{exercises.map(([n,r],i)=><button className={`row ${done[i]?'rowdone':''}`} key={n} onClick={()=>setDone(x=>({...x,[i]:!x[i]}))}><div><b>{n}</b><span>{r}</span></div><strong>{done[i]?'✓':'○'}</strong></button>)}</div></section><div className="tip">Progressive overload: tambah reps, set, pause, atau tempo saat 10 kg mulai terasa ringan.</div></AppShell>}
